-- get_admin_role: returns the active role for a user (NULL if not admin)
CREATE OR REPLACE FUNCTION public.get_admin_role(
  p_user_id uuid DEFAULT auth.uid()
)
RETURNS text
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT role
  FROM public.admin_users
  WHERE user_id = p_user_id
    AND is_active = true
  LIMIT 1;
$$;

-- is_o_super_admin
CREATE OR REPLACE FUNCTION public.is_o_super_admin(
  p_user_id uuid DEFAULT auth.uid()
)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.admin_users
    WHERE user_id = p_user_id
      AND role = 'o_super_admin'
      AND is_active = true
  );
$$;

-- is_p_super_admin
CREATE OR REPLACE FUNCTION public.is_p_super_admin(
  p_user_id uuid DEFAULT auth.uid()
)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.admin_users
    WHERE user_id = p_user_id
      AND role = 'p_super_admin'
      AND is_active = true
  );
$$;

-- is_super_admin (exactly super_admin, not higher)
CREATE OR REPLACE FUNCTION public.is_super_admin(
  p_user_id uuid DEFAULT auth.uid()
)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.admin_users
    WHERE user_id = p_user_id
      AND role = 'super_admin'
      AND is_active = true
  );
$$;

-- is_admin_staff: true if user has ANY active admin role
CREATE OR REPLACE FUNCTION public.is_admin_staff(
  p_user_id uuid DEFAULT auth.uid()
)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.admin_users
    WHERE user_id = p_user_id
      AND is_active = true
  );
$$;

-- can_unban_users: ONLY o_super_admin
CREATE OR REPLACE FUNCTION public.can_unban_users(
  p_user_id uuid DEFAULT auth.uid()
)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT public.is_o_super_admin(p_user_id);
$$;

